#include "core/Story.h"
#include "core/TimelineOps.h"
#include "core/Compositor.h"
#include "core/AudioMixer.h"
#include "core/GpuCompositor.h"
#include "core/FrameRenderer.h"
#include <QGuiApplication>
#include <QOffscreenSurface>
#include <QTemporaryDir>
#include <QTextStream>
#include <cmath>
int main(int argc,char** argv) {
    QGuiApplication app(argc,argv);int failures=0;
    auto check=[&](bool ok,const QString& what){QTextStream(stdout)<<(ok?"PASS ":"FAIL ")<<what<<Qt::endl;if(!ok)++failures;};
    if(argc<2)return 2;Project p;const auto info=probeMedia(QString::fromLocal8Bit(argv[1]));check(info.ok()&&info.hasAudio()&&info.hasVideo(),"audio/video fixture");if(!info.ok())return 1;
    int media=p.addMedia(info);Timeline original=p.timeline();auto placed=ops::insertMedia(original,*p.mediaItem(media),2*kUsPerSecond,-1,p.settings().fps,true);std::set<int> ids(placed.begin(),placed.end());
    for(int id:ids)original.findClip(id)->length=2*kUsPerSecond;
    int video=-1,audio=-1;for(size_t i=0;i<original.tracks.size();++i)if(!original.tracks[i].clips.empty())(isVisualTrack(original.tracks[i].type)?video:audio)=int(i);
    original.tracks[size_t(audio)].level=.6f;original.tracks[size_t(audio)].effects.push_back(makeEffectOfType("a_gain",original.allocId()));original.tracks[size_t(audio)].effects.back().params["gain"].value=-3;
    p.applyEdit(original,"fixture");Compositor beforeRenderer(true);const auto frame=beforeRenderer.render(*p.snapshot(),2500000,{640,360});AudioMixer beforeMixer(48000);std::vector<float> samples(2048);beforeMixer.mix(*p.snapshot(),120000,1024,samples.data());
    Timeline packed=original;QString error;auto containers=story::compound(packed,ids,"Chapter one",&error);check(containers.size()==2&&error.isEmpty(),"compound creates paired picture and sound");check(packed.tracks.size()==original.tracks.size(),"packing collapses selected source tracks");check(timelineProblem(packed).isEmpty(),"packed timeline invariants");p.applyEdit(packed,"pack");
    Compositor packedRenderer(true);const auto packedFrame=packedRenderer.render(*p.snapshot(),2500000,{640,360});check(packedFrame==frame,"compound CPU picture matches original");AudioMixer packedMixer(48000);std::vector<float> packedSamples(2048);packedMixer.mix(*p.snapshot(),120000,1024,packedSamples.data());double difference=0,peak=0;for(size_t i=0;i<samples.size();++i){difference=std::max(difference,double(std::abs(samples[i]-packedSamples[i])));peak=std::max(peak,double(std::abs(samples[i])));}check(peak>1e-5&&difference<1e-5,"compound retains real audio and track gain/effects");
    check(p.isMediaUsed(media)&&!p.removeMedia(media),"nested source media protected from removal");p.undoStack()->undo();check(p.timeline()==original,"one undo restores source tracks");p.undoStack()->redo();check(p.timeline()==packed,"redo restores nested content");
    QTemporaryDir folder;QString path=folder.path()+"/nested.mvp";check(p.save(path,&error),"save compound project");Project loaded;check(loaded.load(path,&error)&&loaded.timeline()==packed,"reload preserves embedded tracks and metadata");
    auto nestedJson=nestedTimelineToJson(*packed.findClip(containers.front())->sequence.value);check(nestedTimelineFromJson(nestedJson)==*packed.findClip(containers.front())->sequence.value,"embedded JSON round trip");
    Timeline unpacked=packed;check(story::unpack(unpacked,containers.front(),&error),"unpack full range");check(timelineProblem(unpacked).isEmpty(),"unpack remaps effect, track, event and group IDs");p.setTimelineLive(unpacked);Compositor unpackRenderer(true);check(unpackRenderer.render(*p.snapshot(),2500000,{640,360})==frame,"unpacked picture stays identical");AudioMixer unpackMixer(48000);std::vector<float> unpackSamples(2048);unpackMixer.mix(*p.snapshot(),120000,1024,unpackSamples.data());difference=0;for(size_t i=0;i<samples.size();++i)difference=std::max(difference,double(std::abs(samples[i]-unpackSamples[i])));check(difference<1e-5,"unpacked sound stays identical");
    auto surface=createGpuSurface();auto gpu=surface?GpuCompositor::create(surface.get(),true,&error):nullptr;check(bool(gpu),"GPU available for sequence check");if(gpu){p.setTimelineLive(packed);const auto gpuFrame=gpu->render(*p.snapshot(),2500000,{640,360});double d=0;auto a=frame.convertToFormat(QImage::Format_RGBA8888),b=gpuFrame.convertToFormat(QImage::Format_RGBA8888);if(a.size()==b.size()){for(int y=0;y<a.height();++y)for(int x=0;x<a.width()*4;++x)d+=std::abs(int(a.constScanLine(y)[x])-int(b.constScanLine(y)[x]));d/=a.width()*a.height()*4;}else d=255;check(d<3,"GPU sequence picture agrees with CPU");}
    Timeline twice=packed;auto second=story::compound(twice,std::set<int>(containers.begin(),containers.end()),"Nested twice",&error);p.setTimelineLive(twice);Compositor twiceRenderer(true);check(second.size()==2&&twiceRenderer.render(*p.snapshot(),2500000,{640,360})==frame,"two nesting levels preserve picture");
    Clip sequence=*packed.findClip(containers.front());ops::setClipSpeed(sequence,nullptr,.5,false,p.settings().fps);check(sequence.length<=4*kUsPerSecond,"sequence speed constrained by source duration");const auto bounds=ops::trimRange(*packed.findClip(containers.front()),nullptr,false);check(bounds.second==0,"sequence cannot trim past source end");
    Timeline storyTl;int first=story::addChapter(storyTl,"Origins","Narration one",2*kUsPerSecond,3*kUsPerSecond,p.mediaItem(media).get(),0,p.settings().fps,&error);int secondChapter=story::addChapter(storyTl,"Evolution","Narration two",3*kUsPerSecond,2*kUsPerSecond,nullptr,0,p.settings().fps,&error);check(first&&secondChapter&&storyTl.duration()==10*kUsPerSecond,"story chapters include separate listening time");check(story::updateChapter(storyTl,first,"Origins revised","New script",3*kUsPerSecond,4*kUsPerSecond,&error),"change chapter duration");check(storyTl.chapters[1].toObject()["start"].toString().toLongLong()==7*kUsPerSecond&&storyTl.duration()==12*kUsPerSecond,"duration change moves later chapters and clips together");check(story::moveChapter(storyTl,first,1,&error)&&storyTl.chapters[0].toObject()["id"].toInt()==secondChapter,"swap adjacent chapters");check(story::removeChapter(storyTl,first,&error)&&storyTl.duration()==5*kUsPerSecond,"delete chapter ripples its full range");check(timelineProblem(storyTl).isEmpty(),"chapter edit invariants");
    Timeline adopted=original;int adoptedId=story::adoptChapter(adopted,"Existing edit","Script",2*kUsPerSecond,3*kUsPerSecond,kUsPerSecond,&error);check(adoptedId&&adopted.chapters[0].toObject()["clips"].toArray().size()==2,"adopt existing range splits and assigns picture/sound");check(!story::adoptChapter(adopted,"Overlap","",2500000,3500000,500000,&error),"overlapping chapters rejected");
    Timeline variation=original,repeated=original;check(story::directorsDice(variation,ids,42,2,.8)==1,"dice varies visual clips");story::directorsDice(repeated,ids,42,2,.8);check(variation==repeated,"dice seed reproduces the same edit");check(variation.tracks[size_t(audio)]==original.tracks[size_t(audio)],"dice leaves sound intact");const auto& old=original.tracks[size_t(video)].clips.front();const auto& changed=variation.tracks[size_t(video)].clips.front();check(old.start==changed.start&&old.length==changed.length&&old.sourceIn==changed.sourceIn&&old.speed==changed.speed,"dice preserves timing/source sync");check(!changed.effects.empty()&&changed.effects.back().params.at("fxMix").at(200000,ParamType::Number)==0,"dice effect accent clears after entrance");
    Timeline markerTimeline=*packed.findClip(containers.front())->sequence.value;Marker marker;marker.id=markerTimeline.allocId();marker.time=100000;marker.name="Beat";markerTimeline.markers.push_back(marker);check(nestedTimelineFromJson(nestedTimelineToJson(markerTimeline))==markerTimeline,"nested markers persist");
    {
        Timeline edited=packed;Timeline content=*packed.findClip(containers.front())->sequence.value;
        for(auto& t:content.tracks)for(auto& c:t.clips)c.length+=kUsPerSecond;
        Track future;future.id=edited.allocId();Clip tail;tail.id=edited.allocId();tail.start=6*kUsPerSecond;tail.length=kUsPerSecond;tail.generator.type="text";future.clips.push_back(tail);edited.tracks.push_back(future);
        Marker chapterMarker;chapterMarker.id=edited.allocId();chapterMarker.time=2*kUsPerSecond;chapterMarker.length=2*kUsPerSecond;edited.markers.push_back(chapterMarker);
        QJsonArray owned;for(int id:containers)owned.append(id);
        edited.chapters.append(QJsonObject{{"id",chapterMarker.id},{"name","Compound chapter"},{"start","2000000"},{"narration","1000000"},{"listening","1000000"},{"clips",owned}});
        edited.chapters.append(QJsonObject{{"id",edited.allocId()},{"name","Following chapter"},{"start","6000000"},{"narration","1000000"},{"listening","0"}});
        check(story::replaceCompound(edited,containers.front(),content,true,&error),"replace compound content with longer edit");check(edited.findClip(tail.id)->start==7*kUsPerSecond&&edited.chapters[1].toObject()["start"].toString()=="7000000","compound duration ripples clips and chapter metadata");check(edited.chapters[0].toObject()["listening"].toString()=="2000000"&&edited.findMarker(chapterMarker.id)->length==3*kUsPerSecond,"compound chapter retains narration window and updates listening span");check(edited.findClip(containers.back())->sequence==edited.findClip(containers.front())->sequence,"picture/audio containers share updated content");
    }
    return failures;
}
